class Solution:
    def getMoneyAmount(self, n: int) -> int:
        dp = [[0]*(n+1) for _ in range(n+1)]
        return self.dfs(1, n, dp)

    def dfs(self, l, r, dp):
        if l >= r:
            return 0
        if dp[l][r]!= 0:
            return dp[l][r]
        res = float('inf')
        for x in range((l+r)//2, r):
            res = min(res, max(self.dfs(l, x-1, dp), self.dfs(x+1, r, dp)) + x)
        dp[l][r] = res
        return res

n = 10
