python
import pulp
import numpy as np

def solution():
    # Define the problem
    cities = list(range(13))
    distances = {}
    for i in range(13):
        for j in range(i+1, 13):
            if i == 0:
                if j == 1:
                    distances[(i, j)] = 61
                elif j == 2:
                    distances[(i, j)] = 55
                # ... (rest of the distances)
            elif i == 1:
                if j == 2:
                    distances[(i, j)] = 80
                elif j == 3:
                    distances[(i, j)] = 115
                # ... (rest of the distances)
            # ... (rest of the distances)

    # Create the LP problem
    model = pulp.LpProblem(name="TSP", sense=pulp.LpMinimize)

    # Create variables
    x = pulp.LpVariable.dicts("x", (cities, cities), 0, 1, cat=pulp.LpInteger)

    # Add objective function
    model += pulp.lpSum([distances[i, j] * x[i][j] for i in cities for j in cities if i < j])

    # Add constraints
    for i in cities:
        model += pulp.lpSum([x[i][j] for j in cities if i != j]) == 1
        model += pulp.lpSum([x[j][i] for j in cities if i != j]) == 1

    # Solve the problem
    status = model.solve()

    # Get the solution
    path = []
    for i in cities:
        for j in cities:
            if x[i][j].value() == 1:
                path.append((i, j))

    # Return the solution
    return [i for i, _ in path], int(pulp.value(model.objective))
