    x = pulp.LpVariable.dicts("Meeting", (range(4), range(5)), 0, 1, cat=pulp.LpInteger)

    # The objective is to maximize the number of meetings scheduled
    prob += pulp.lpSum([x[i][j] for i in range(4) for j in range(5)])

    # Each meeting must be scheduled at most once
    for i in range(4):
        prob += pulp.lpSum([x[i][j] for j in range(5)]) <= 1

    # Each time slot can be used at most once
    for j in range(5):
        prob += pulp.lpSum([x[i][j] for i in range(4)]) <= 1

    # Available time slots for each participant
    for i, available_slots in enumerate([[1, 2, 3, 4], [0, 1, 2, 3], [1, 2], [4]]):
        for j in range(5):
            if j + 1 not in available_slots:
                prob += x[i][j] == 0

    # Solve the problem
    prob.solve()

    # Extract the solution
    meet2time = {}
    for i in range(4):
        for j in range(5):
            if x[i][j].varValue == 1:
                if i not in meet2time:
                    meet2time[i] = []
                meet2time[i].append(j + 1)

    return meet2time
