def solution():
    from pulp import LpMaximize, LpProblem, LpStatus, lpSum, LpVariable
    # Create the 'prob' variable to contain the problem data
    prob = LpProblem("Meeting Scheduling", LpMaximize)

    # The problem variables
    participants = ['0', '1', '2', '3']
    time_slots = ['0', '1', '2', '3', '4']

    # Create problem variables
    meet_vars = LpVariable.dicts("Meet", (participants, time_slots), 0, 1, cat='Binary')

    # The objective is to maximize the number of meetings
    prob += lpSum([meet_vars[p][t] for p in participants for t in time_slots])

    # Add constraints: each participant can only attend one meeting
    for p in participants:
        prob += lpSum([meet_vars[p][t] for t in time_slots]) <= 1

    # Add constraints: each time slot can only be assigned to one meeting
    for t in time_slots:
        prob += lpSum([meet_vars[p][t] for p in participants]) <= 1

    # Add constraints: participants can only attend available time slots
    participant_availability = {
        '0': ['0', '3', '4'],
        '1': ['0', '1', '3', '4'],
        '2': ['3', '4'],
        '3': ['0', '1', '2', '3', '4']
    }
    for p, avails in participant_availability.items():
        for t in time_slots:
            if t not in avails:
                prob += meet_vars[p][t] == 0

    # The problem is solved using PuLP's choice of Solver
    prob.solve()

    # The status of the solution is printed to the screen
    print("Status:", LpStatus[prob.status])

    # Each of the variables is printed with its resolved optimum value
    meet2time = {}
    for p in participants:
        for t in time_slots:
            if meet_vars[p][t].varValue:
                if p not in meet2time:
                    meet2time[int(p)] = [int(t)]
                else:
                    meet2time[int(p)].append(int(t))

    return meet2time
```
