import pulp

def solution():
    # Define the problem
    model = pulp.LpProblem("MeetingScheduling", pulp.LpMinimize)

    # Define the participants and time slots
    participants = {0, 1, 2, 3}
    time_slots = {0, 1, 2, 3, 4}

    # Define the available time slots for each participant
    available_slots = {
        0: [2, 4],
        1: [0, 2, 3],
        2: [4],
        3: [0, 1, 2, 3]
    }

    # Define the meetings for each participant
    meetings = {
        0: [0, 2],
        1: [2, 0],
        2: [0, 2, 1],
        3: [2]
    }

    # Define the variables
    x = pulp.LpVariable.dicts("x", (participants, time_slots), 0, 1, pulp.LpInteger)

    # Add constraints: each participant can only attend one meeting
    for p in participants:
        model += pulp.lpSum([x[p][t] for t in available_slots[p]]) == 1

    # Add constraints: each time slot can only be assigned to one participant
    for t in time_slots:
        model += pulp.lpSum([x[p][t] for p in participants if t in available_slots[p]]) <= 1

    # Add constraints: each meeting must be attended by all participants
    for p, meeting_participants in meetings.items():
        for t in available_slots[p]:
            model += x[p][t] == pulp.lpSum([x[q][t] for q in meeting_participants])

    # Solve the problem
    model.solve()

    # Extract the solution
    meet2time = {}
    for p in participants:
        for t in available_slots[p]:
            if x[p][t].value() == 1:
                meet2time[p] = [t]
                break

    return meet2time
