def solution():
    from pulp import LpMaximize, LpProblem, LpStatus, lpSum, LpVariable, value
    participants = {'0': {'available_slots': [0, 1, 2, 3], 'meetings': [3, 1, 2]},
                     '1': {'available_slots': [3], 'meetings': [0, 3]},
                     '2': {'available_slots': [0, 2, 5], 'meetings': [3, 2]},
                     '3': {'available_slots': [2, 3, 4, 5], 'meetings': [2, 1]},
                     '4': {'available_slots': [0, 1, 2, 3, 4, 5], 'meetings': [2, 0, 3, 1]}}
    num_participants = len(participants)
    num_slots = 6
    problem = LpProblem(name="meeting-scheduling", sense=LpMaximize)
    meeting_vars = LpVariable.dicts("Meeting", range(num_participants), 0, num_slots-1, cat='Integer')
    for p in participants:
        for s in range(num_slots):
            if s not in participants[p]['available_slots']:
                problem += meeting_vars[int(p)] != s
    for p1 in participants:
        for p2 in participants:
            if p1 != p2:
                problem += meeting_vars[int(p1)] == meeting_vars[int(p2)]
    problem.solve()
    meet2time = {}
    for p in participants:
        meet2time[int(p)] = [value(meeting_vars[int(p)])]
    return str(meet2time)
